// [vite-esm] imports auto-generated by the 2026-07 Vite migration.
import "../state.js";
import "./planner_model.js";

/**
 * Substitution module — entry point.
 *
 * Listens for `app:substitutions` from the Timetable ribbon menu and opens a
 * dialog that walks the user through:
 *   1. Pick a date + absent teachers   (absence_input.js)
 *   2. Generate ranked candidates       (candidate_ranker.js)
 *   3. Review class-wise output         (classwise_output.js)
 *   4. Review teacher-wise output       (teacherwise_output.js)
 *   5. Print A4 memo                    (print_memo.js)
 *
 * Holds shared state on APP.substitution: { date, absent[], assignments[] }
 * (assignments mutate when the user picks an alternate substitute in
 * classwise_output.)
 *
 * Stays out of every other module's way — no global side effects beyond
 * `APP.substitution` and the dialog overlay it owns.
 */
(function () {
  "use strict";

  const APP = window.APP;
  if (!APP) return;

  // ---------------- state ----------------
  function mutateCompat(label, fn, opts) {
    if (window.APP && typeof window.APP.mutate === "function") {
      return window.APP.mutate(label, fn, opts);
    }
    const school = window.APP?.school;
    return fn(school);
  }

  function initState() {
    APP.substitution = APP.substitution || {
      date: (window.APP?.editor?.date) || todayYmd(),
      absent: [],           // teacher IDs
      assignments: [],      // [{slotKey, classSection, period, subject, originalTeacher, candidates, chosen}]
    };
    return APP.substitution;
  }

  function todayYmd() {
    const d = new Date();
    const yyyy = d.getFullYear();
    const mm = String(d.getMonth() + 1).padStart(2, "0");
    const dd = String(d.getDate()).padStart(2, "0");
    return `${yyyy}-${mm}-${dd}`;
  }

  // Mon=0..Sat=5 (matches parse_timetable_xml day indexing). Sunday → -1.
  function ymdToDay(ymd) {
    if (!ymd) return 0;
    const parts = ymd.split("-").map(Number);
    if (parts.length !== 3) return 0;
    const js = new Date(parts[0], parts[1] - 1, parts[2]).getDay(); // 0=Sun..6=Sat
    if (js === 0) return -1;
    return js - 1; // Mon=0..Sat=5
  }

  // ---------------- DOM helpers ----------------
  function el(tag, attrs, ...kids) {
    const n = document.createElement(tag);
    if (attrs) for (const k in attrs) {
      const v = attrs[k];
      if (v == null) continue;
      if (k === "class") n.className = v;
      else if (k === "html") n.innerHTML = v;
      else if (k.startsWith("on") && typeof v === "function") n.addEventListener(k.slice(2), v);
      else n.setAttribute(k, v);
    }
    for (const c of kids) if (c != null && c !== false) {
      n.appendChild(typeof c === "string" ? document.createTextNode(c) : c);
    }
    return n;
  }

  function esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"']/g, c =>
      ({ "&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;" }[c]));
  }

  // ---------------- dialog ----------------
  let host = null;

  function open() {
    if (!APP.school) {
      alert("Load a timetable XML first.");
      return;
    }
    initState();
    if (host) host.remove();
    host = buildShell();
    document.body.appendChild(host);
    document.addEventListener("keydown", onKey, true);
    renderTab("absence");
  }

  function close() {
    document.removeEventListener("keydown", onKey, true);
    if (host) { host.remove(); host = null; }
  }

  function onKey(e) {
    if (e.key === "Escape") { e.preventDefault(); close(); }
  }

  function buildShell() {
    const root = el("div", { class: "chrx-sub-dialog", role: "dialog", "aria-modal": "true",
      onclick: (e) => { if (e.target === root) close(); } });
    const panel = el("div", { class: "chrx-sub-panel" });

    panel.appendChild(el("header", { class: "chrx-sub-head" },
      el("h2", null, "Substitution planner"),
      el("nav", { class: "chrx-sub-tabs" },
        el("button", { class: "chrx-sub-tab is-active", "data-tab": "absence",
          onclick: () => renderTab("absence") }, "1. Absent teachers"),
        el("button", { class: "chrx-sub-tab", "data-tab": "classwise",
          onclick: () => renderTab("classwise") }, "2. Class-wise"),
        el("button", { class: "chrx-sub-tab", "data-tab": "teacherwise",
          onclick: () => renderTab("teacherwise") }, "3. Teacher-wise"),
        el("button", { class: "chrx-sub-tab", "data-tab": "print",
          onclick: () => renderTab("print") }, "4. Print memo"),
      ),
      el("button", { class: "chrx-sub-x", "aria-label": "Close", onclick: close }, "×"),
    ));

    panel.appendChild(el("section", { class: "chrx-sub-body", id: "chrx-sub-body" }));
    root.appendChild(panel);
    return root;
  }

  function renderTab(tab) {
    if (!host) return;
    host.querySelectorAll(".chrx-sub-tab").forEach(b => {
      b.classList.toggle("is-active", b.dataset.tab === tab);
    });
    const body = host.querySelector("#chrx-sub-body");
    body.innerHTML = "";

    const s = APP.substitution;
    switch (tab) {
      case "absence":
        window.SubstitutionAbsence.render(body, s, () => {
          // After generate, jump to class-wise output.
          renderTab("classwise");
        });
        break;
      case "classwise":
        window.SubstitutionClasswise.render(body, s, () => renderTab("classwise"));
        break;
      case "teacherwise":
        window.SubstitutionTeacherwise.render(body, s);
        break;
      case "print":
        window.SubstitutionPrintMemo.render(body, s);
        break;
    }
  }

  // ---------------- C3 Data model & operations ----------------
  //
  // The plan is the working state of one day's substitutions; `school` is only
  // written when the user applies something. That split is the standalone
  // planner's best idea: preview a whole day, then accept or undo it, without
  // half-applied state in the document.
  //
  //   plan = { date, day, absent:[{teacherId,type}], dutyPool:[ids],
  //            slots:[slot], actingCT:{classId: teacherId} }
  //
  // Everything the engine needs lives on the plan, so buildSmartPlan can run on
  // a copy and the UI can diff the result.
  const P = () => window.SmartPlanner;

  function emptyPlan(date) {
    return { date, day: ymdToDay(date), absent: [], dutyPool: [], slots: [], actingCT: {} };
  }

  /** Slots = every card the absent teachers would have taught on that weekday. */
  function buildPlan(school, date, opts = {}) {
    const s = school || window.APP?.school;
    const plan = emptyPlan(date);
    if (!s) return plan;
    const idx = s._idx || {};
    const day = plan.day;

    const absenceRows = (s.absences || []).filter((a) => a.date === date);
    const absentIds = opts.absentIds && opts.absentIds.length
      ? opts.absentIds.slice()
      : absenceRows.map((a) => a.teacherId);
    // Ids only (the chips/tabs/tests read this), with the reason carried beside
    // it. Older code used objects here and every consumer had to know which.
    plan.absent = absentIds.slice();
    plan.absentTypes = Object.create(null);
    for (const teacherId of absentIds) {
      const row = absenceRows.find((a) => a.teacherId === teacherId);
      plan.absentTypes[teacherId] = (row && row.type) || "Sick";
    }

    plan.dutyPool = (s.dutyPool || [])
      .filter((d) => d && d.date === date)
      .flatMap((d) => d.teacherIds || []);

    const saved = (s.substitutions || []).filter((x) => x.date === date);

    const rows = window.SmartPlanner ? window.SmartPlanner.timetableRows(s) : [];
    for (const teacherId of absentIds) {
      const teacher = idx.teacherById?.[teacherId];
      // Timetable rows, not the `_idx` index: recording the absence itself is a
      // mutation, and the undo layer rebuilds `_idx` without the per-card lesson
      // context (see planner_model.timetableRows).
      const teacherRows = rows.filter((r) => r.teacherIds.includes(teacherId));
      for (const row of teacherRows) {
        const card = row.card;
        if (card.day !== day) continue;
        const lesson = row.lesson || {};
        const classId = (lesson.classIds || [])[0] || "";
        const cardId = card.cardId || card.id || `placed_${card.lessonId}_${card.day}_${card.period}`;
        const slotKey = `${card.period}::${classId}::${teacherId}`;
        const sub = saved.find((x) => x.slotKey === slotKey || x.cardId === cardId);
        plan.slots.push({
          slotKey,
          period: card.period,
          day,
          classId,
          classSection: idx.classById?.[classId]?.name || classId,
          subjectId: lesson.subjectId || "",
          subject: idx.subjectById?.[lesson.subjectId]?.name || "",
          absentTeacherId: teacherId,
          absentTeacher: teacher?.name || teacherId,
          cardId,
          lessonId: lesson.id || card.lessonId,
          classroomId: card.classroomId,
          status: (sub && sub.status) || (sub && sub.substituteTeacherId ? "FILLED" : "PENDING"),
          type: (sub && sub.type) || "SUB",
          substituteTeacherId: (sub && sub.substituteTeacherId) || null,
          substituteTeacher: (sub && sub.substituteTeacherId && idx.teacherById?.[sub.substituteTeacherId]?.name) || "",
          mergedWithKey: (sub && sub.mergedWithKey) || null,
          movedFrom: (sub && sub.movedFrom) || null,
          smartScore: sub ? sub.smartScore : undefined,
          smartReason: sub ? sub.smartReason : "",
          note: (sub && sub.note) || "",
        });
      }
    }
    plan.slots.sort((a, b) => a.period - b.period || String(a.classSection).localeCompare(String(b.classSection)));

    for (const row of (s.actingCT || []).filter((r) => r.date === date)) {
      plan.actingCT[row.classId] = row.teacherId;
    }

    // Legacy projection: the older renderers and the existing e2e read
    // `assignments`. Keep it exact rather than rewrite every caller at once.
    plan.assignments = projectAssignments(s, plan);
    return plan;
  }

  function projectAssignments(s, plan) {
    const ranker = window.SubstitutionRanker;
    return (plan.slots || []).map((slot) => {
      const candidates = ranker && ranker.rankSlot ? ranker.rankSlot(s, plan, slot) : [];
      const chosen = slot.substituteTeacherId
        ? candidates.find((c) => c.teacherId === slot.substituteTeacherId) || {
            teacherId: slot.substituteTeacherId,
            teacher: slot.substituteTeacher || slot.substituteTeacherId,
            score: slot.smartScore || 0,
            reasons: slot.smartReason ? [slot.smartReason] : [],
          }
        : null;
      return {
        slotKey: slot.slotKey,
        cardId: slot.cardId,
        classId: slot.classId,
        classSection: slot.classSection,
        period: slot.period,
        subject: slot.subject,
        subjectId: slot.subjectId,
        originalTeacher: slot.absentTeacher,
        originalTeacherId: slot.absentTeacherId,
        candidates,
        allCandidates: candidates,
        chosen,
        cancelled: slot.status === "CANCELLED",
        supervised: slot.status === "SUPERVISED",
        uncovered: !chosen && slot.status !== "CANCELLED",
        status: slot.status,
        type: slot.type,
      };
    });
  }

  /** Write the whole plan back to the document in ONE mutation (one undo step). */
  function persistPlan(school, plan, label) {
    const s = school || window.APP?.school;
    if (!s) return null;
    return mutateCompat(label || "Save substitutions", (targetSchool) => {
      const sc = targetSchool || s;
      const date = plan.date;

      sc.absences = (sc.absences || []).filter((a) => a.date !== date);
      const absentIds = P().absentIdsOf(plan);
      const types = plan.absentTypes || {};
      for (const teacherId of absentIds) {
        sc.absences.push({
          id: `abs_${date}_${teacherId}`,
          date,
          teacherId,
          periods: "all",
          type: types[teacherId] || "Sick",
          reason: "",
        });
      }

      sc.dutyPool = (sc.dutyPool || []).filter((d) => d && d.date !== date);
      if ((plan.dutyPool || []).length) sc.dutyPool.push({ date, teacherIds: plan.dutyPool.slice() });

      sc.actingCT = (sc.actingCT || []).filter((r) => r && r.date !== date);
      for (const classId of Object.keys(plan.actingCT || {})) {
        if (plan.actingCT[classId]) {
          sc.actingCT.push({ date, classId, teacherId: plan.actingCT[classId] });
        }
      }

      const others = (sc.substitutions || []).filter((x) => x.date !== date);
      const rows = [];
      for (const slot of plan.slots || []) {
        // Nothing decided yet → nothing to record.
        if (!slot.substituteTeacherId && slot.status === "PENDING") continue;
        rows.push({
          id: `sub_${date}_${slot.period}_${slot.classId}`,
          date,
          day: slot.day != null ? slot.day : ymdToDay(date),
          period: slot.period,
          slotKey: slot.slotKey,
          cardId: slot.cardId,
          classId: slot.classId,
          subjectId: slot.subjectId,
          absentTeacherId: slot.absentTeacherId,
          substituteTeacherId: slot.substituteTeacherId || null,
          status: slot.status,
          type: slot.type || "SUB",
          mergedWithKey: slot.mergedWithKey || null,
          movedFrom: slot.movedFrom || null,
          smartScore: slot.smartScore != null ? slot.smartScore : undefined,
          smartReason: slot.smartReason || "",
          roomId: slot.classroomId || undefined,
          note: slot.note || "",
          createdAt: new Date().toISOString(),
        });
      }
      sc.substitutions = others.concat(rows);

      if (window.APP?.substitution) {
        window.APP.substitution.date = date;
        window.APP.substitution.absent = P().absentIdsOf(plan);
        window.APP.substitution.dutyPool = (plan.dutyPool || []).slice();
        window.APP.substitution.slots = plan.slots;
        window.APP.substitution.actingCT = plan.actingCT || {};
        window.APP.substitution.assignments = projectAssignments(sc, plan);
      }

      window.dispatchEvent(new CustomEvent("substitution:saved", { detail: { date } }));
      document.dispatchEvent(new CustomEvent("app:school-changed",
        { detail: { label: label || "Save substitutions", source: "mutate" } }));
      return rows;
    });
  }

  /** Rebuild APP.substitution from the document (called on open). */
  function loadPlan(school, date) {
    const s = school || window.APP?.school;
    const plan = buildPlan(s, date);
    APP.substitution = Object.assign(APP.substitution || {}, plan);
    return plan;
  }

  // ---- slot edits (on the in-memory plan; persistPlan writes them) ----

  function setSubstitute(plan, slotKeyValue, teacherId, opts = {}) {
    const target = (plan.slots || []).find((s) => s.slotKey === slotKeyValue);
    if (!target) return null;
    if (!teacherId) {
      target.substituteTeacherId = null;
      target.substituteTeacher = "";
      target.status = "PENDING";
      target.type = "SUB";
      delete target.smartScore;
      target.smartReason = "";
      syncMerge(plan, target);
      return target;
    }
    const teacher = window.APP?.school?._idx?.teacherById?.[teacherId];
    target.substituteTeacherId = teacherId;
    target.substituteTeacher = teacher?.name || teacherId;
    target.status = opts.supervision ? "SUPERVISED" : "FILLED";
    target.type = opts.supervision ? "SUPERVISION" : "SUB";
    if (opts.score != null) target.smartScore = opts.score;
    if (opts.reason) target.smartReason = opts.reason;
    syncMerge(plan, target);
    return target;
  }

  function setCancelled(plan, slotKeyValue, cancelled = true) {
    const slot = (plan.slots || []).find((s) => s.slotKey === slotKeyValue);
    if (!slot) return null;
    slot.status = cancelled ? "CANCELLED" : "PENDING";
    slot.type = cancelled ? "CANCEL" : "SUB";
    slot.substituteTeacherId = null;
    slot.substituteTeacher = "";
    delete slot.smartScore;
    slot.smartReason = "";
    syncMerge(plan, slot);
    return slot;
  }

  function movePeriod(plan, slotKeyValue, period) {
    const slot = (plan.slots || []).find((s) => s.slotKey === slotKeyValue);
    if (!slot || !(period > 0)) return null;
    if (slot.movedFrom == null) slot.movedFrom = slot.period;
    slot.period = period;
    if (slot.substituteTeacherId) {
      slot.substituteTeacherId = null;
      slot.substituteTeacher = "";
      slot.status = "PENDING";
      slot.type = "SUB";
      delete slot.smartScore;
      slot.smartReason = "";
    }
    plan.slots.sort((a, b) => a.period - b.period || String(a.classSection).localeCompare(String(b.classSection)));
    return slot;
  }

  function mergeSlots(plan, slotKeyA, slotKeyB) {
    const a = (plan.slots || []).find((s) => s.slotKey === slotKeyA);
    const b = (plan.slots || []).find((s) => s.slotKey === slotKeyB);
    if (!a || !b || a === b || +a.period !== +b.period) return null;
    a.mergedWithKey = b.slotKey;
    b.mergedWithKey = a.slotKey;
    const done = (a.substituteTeacherId && a.status !== "PENDING") ? a
      : (b.substituteTeacherId && b.status !== "PENDING") ? b : null;
    if (done) {
      for (const s of [a, b]) {
        s.substituteTeacherId = done.substituteTeacherId;
        s.substituteTeacher = done.substituteTeacher;
        s.status = done.status;
        s.type = done.type;
      }
    }
    return [a, b];
  }

  function unmergeSlots(plan, slotKeyValue) {
    const a = (plan.slots || []).find((s) => s.slotKey === slotKeyValue);
    if (!a || !a.mergedWithKey) return null;
    const b = (plan.slots || []).find((s) => s.slotKey === a.mergedWithKey);
    a.mergedWithKey = null;
    if (b) b.mergedWithKey = null;
    return [a, b].filter(Boolean);
  }

  /** A merged pair always shares one substitute. */
  function syncMerge(plan, slot) {
    if (!slot || !slot.mergedWithKey) return;
    const partner = (plan.slots || []).find((s) => s.slotKey === slot.mergedWithKey);
    if (!partner) { slot.mergedWithKey = null; return; }
    partner.substituteTeacherId = slot.substituteTeacherId;
    partner.substituteTeacher = slot.substituteTeacher;
    partner.status = slot.status;
    partner.type = slot.type;
    if (slot.smartScore != null) partner.smartScore = slot.smartScore;
    partner.smartReason = slot.smartReason || "";
  }

  // ---- the planner's headline action ----

  /** Fill everything the policy is willing to fill. Returns the preview. */
  function planSmartFill(school, plan) {
    return P().buildSmartPlan(school || window.APP?.school, plan);
  }

  /** Apply a previewed plan: one mutation, one undo step. */
  function applySmartFill(school, plan, preview) {
    const next = (preview && preview.plan) || plan;
    const s = school || window.APP?.school;
    window.APP.substitution = Object.assign(window.APP.substitution || {}, next, {
      assignments: projectAssignments(s, next),
    });
    persistPlan(s, next, "Smart auto-fill substitutions");
    return next;
  }

  /** Undo = reload the plan from the document (⌘Z also holds the mutation). */
  function undoSmartFill(school) {
    const s = school || window.APP?.school;
    return loadPlan(s, (window.APP?.substitution || {}).date || todayYmd());
  }

  // ---- single-slot operations (used by the chips, the grid and the board) ----

  function recordAbsence(school, { date, teacherId, periods = "all", reason = "", type = "Sick" }) {
    const s = school || window.APP?.school;
    if (!s) return null;
    return mutateCompat("Record absence", (targetSchool) => {
      const sc = targetSchool || s;
      sc.absences = sc.absences || [];
      let abs = sc.absences.find((a) => a.date === date && a.teacherId === teacherId);
      if (abs) {
        abs.periods = periods || "all";
        abs.type = type || abs.type || "Sick";
        if (reason) abs.reason = reason;
      } else {
        abs = {
          id: `abs_${date}_${teacherId}`,
          date,
          teacherId,
          periods: periods || "all",
          type: type || "Sick",
          reason: reason || "",
        };
        sc.absences.push(abs);
      }
      if (window.APP?.substitution && window.APP.substitution.date === date) {
        const planAbsent = window.APP.substitution.absent;
        if (Array.isArray(planAbsent) && !planAbsent.includes(teacherId)) planAbsent.push(teacherId);
        window.APP.substitution.absentTypes = window.APP.substitution.absentTypes || {};
        window.APP.substitution.absentTypes[teacherId] = type || "Sick";
      }
      return abs;
    });
  }

  function cancelSubstitution(school, { id, date, cardId, slotKey: key }) {
    const s = school || window.APP?.school;
    if (!s) return null;
    const plan = loadPlan(s, date);
    const slot = findSlot(plan, s, { id, date, cardId, slotKey: key });
    if (!slot) return null;
    setCancelled(plan, slot.slotKey, true);
    persistPlan(s, plan, "Cancel substitution");
    return slot;
  }

  /**
   * Locate a slot from whichever handle the caller has: the persisted row id,
   * a cardId, a slotKey, or the (period, class, absent teacher) triple.
   * Callers historically passed only `id`, so ignoring it silently cancelled
   * nothing (the dated-grid test caught exactly that).
   */
  function findSlot(plan, school, { id, date, cardId, slotKey: key, period, classId, absentTeacherId }) {
    if (key) {
      const byKey = (plan.slots || []).find((x) => x.slotKey === key);
      if (byKey) return byKey;
    }
    if (cardId) {
      const byCard = (plan.slots || []).find((x) => x.cardId === cardId);
      if (byCard) return byCard;
    }
    if (id) {
      const row = (school.substitutions || []).find((x) => x.id === id);
      if (row) {
        const byRow = (plan.slots || []).find(
          (x) => (row.slotKey && x.slotKey === row.slotKey) ||
                 (row.cardId && x.cardId === row.cardId) ||
                 (+x.period === +row.period && x.classId === row.classId && x.absentTeacherId === row.absentTeacherId)
        );
        if (byRow) return byRow;
      }
    }
    if (period != null) {
      return (plan.slots || []).find(
        (x) => +x.period === +period &&
               (!classId || x.classId === classId) &&
               (!absentTeacherId || x.absentTeacherId === absentTeacherId)
      ) || null;
    }
    return null;
  }

  function reassignSubstitution(school, { id, date, cardId, slotKey: key, substituteTeacherId }) {
    const s = school || window.APP?.school;
    if (!s) return null;
    const plan = loadPlan(s, date);
    const slot = findSlot(plan, s, { id, date, cardId, slotKey: key });
    if (!slot) return null;
    setSubstitute(plan, slot.slotKey, substituteTeacherId || null);
    persistPlan(s, plan, substituteTeacherId ? "Reassign substitution" : "Clear substitute");
    return slot;
  }

  // ---- legacy entry points, re-expressed on the plan ----

  /**
   * Legacy bulk assign — "give every affected period a substitute".
   *
   * The policy leaves a slot open when nothing scores above its minimum, which
   * is right for the planner UI but wrong for this contract: callers of
   * assignSubstitutions (the dated grid, older tests) expect every candidate
   * slot to end up with a name. So: run the policy, then fill anything it left
   * open with the best available teacher, ignoring the minimum.
   */
  function assignSubstitutions(school, date, absentTeacherIds) {
    const s = school || window.APP?.school;
    const plan = buildPlan(s, date, { absentIds: absentTeacherIds });
    const preview = planSmartFill(s, plan);
    const filled = preview.plan;
    const P2 = P();
    for (const slot of filled.slots || []) {
      if (P2.isFilled(slot) || slot.status === "CANCELLED") continue;
      const best = (window.SubstitutionRanker.rankSlot(s, filled, slot) || [])
        .filter((c) => !c.alreadyInSlot)[0];
      if (!best) continue;
      slot.substituteTeacherId = best.teacherId;
      slot.substituteTeacher = best.teacher;
      slot.status = "FILLED";
      slot.type = slot.type === "SUPERVISION" ? "SUPERVISION" : "SUB";
      slot.smartScore = best.score;
      slot.smartReason = (best.why || []).slice(0, 3).join(" · ") || "best available";
    }
    return applySmartFill(s, plan, { plan: filled }).slots;
  }

  function removeAbsence(school, { date, teacherId }) {
    const s = school || window.APP?.school;
    if (!s) return;
    return mutateCompat("Remove absence", (targetSchool) => {
      const sc = targetSchool || s;
      sc.absences = (sc.absences || []).filter((a) => !(a.date === date && a.teacherId === teacherId));
      sc.substitutions = (sc.substitutions || []).filter(
        (sub) => !(sub.date === date && sub.absentTeacherId === teacherId)
      );
      const plan = window.APP?.substitution;
      if (plan && plan.date === date) {
        plan.absent = P().absentIdsOf(plan).filter((id) => id !== teacherId);
        plan.slots = (plan.slots || []).filter((sl) => sl.absentTeacherId !== teacherId);
        plan.assignments = projectAssignments(sc, plan);
      }
    });
  }

  function getAbsences(school, date) {
    const s = school || window.APP?.school;
    if (!s || !s.absences) return [];
    return date ? s.absences.filter((a) => a.date === date) : s.absences.slice();
  }

  function getSubstitutions(school, date) {
    const s = school || window.APP?.school;
    if (!s || !s.substitutions) return [];
    return date ? s.substitutions.filter((sub) => sub.date === date) : s.substitutions.slice();
  }

  // ---------------- Dated view grid hook ----------------
  function applyGridOverrides(rootEl, S) {
    if (!rootEl || !S) return;
    const selectedDate = window.APP?.editor?.date;
    if (!selectedDate) return;

    const day = ymdToDay(selectedDate);
    if (day < 0) return;

    const substitutions = (S.substitutions || []).filter(s => s.date === selectedDate && s.day === day);
    if (!substitutions.length) return;

    const perspective = window.APP?.editor?.perspective || "class";

    substitutions.forEach(sub => {
      const isCancelled = sub.substituteTeacherId === null;
      const subTeacher = sub.substituteTeacherId
        ? (S._idx?.teacherById?.[sub.substituteTeacherId]?.name || sub.substituteTeacherId)
        : null;
      const origTeacher = (sub.absentTeacherId && S._idx?.teacherById?.[sub.absentTeacherId]?.name) || sub.absentTeacherId;

      // 1. Affected original card(s)
      const cardEls = rootEl.querySelectorAll(`.chrx-vkarta[data-card-id="${sub.cardId}"]`);
      cardEls.forEach(cardEl => {
        if (cardEl.classList.contains("chrx-vkarta--substitute")) return;
        const line2 = cardEl.querySelector(".chrx-vk-line2");
        const line1 = cardEl.querySelector(".chrx-vk-line1");

        if (isCancelled) {
          cardEl.classList.add("chrx-vkarta--cancelled");
          cardEl.style.opacity = "0.75";
          if (line2) {
            line2.innerHTML = `<span style="text-decoration:line-through;opacity:0.6">${esc(origTeacher)}</span> <span class="chrx-sub-badge" style="background:#fee2e2;color:#b91c1c;padding:0 3px;border-radius:3px;font-size:9px;">Cancelled</span>`;
          } else if (line1) {
            line1.innerHTML = `<span style="text-decoration:line-through;opacity:0.6">${line1.innerHTML}</span> <span class="chrx-sub-badge" style="background:#fee2e2;color:#b91c1c;padding:0 3px;border-radius:3px;font-size:9px;">Cancelled</span>`;
          }
        } else if (subTeacher) {
          cardEl.classList.add("chrx-vkarta--substituted");
          if (line2) {
            line2.innerHTML = `<span style="text-decoration:line-through;opacity:0.6">${esc(origTeacher)}</span> ➔ <b style="color:var(--chrx-accent,#2563eb);">${esc(subTeacher)}</b>`;
          } else if (line1) {
            line1.innerHTML += ` ➔ <b style="color:var(--chrx-accent,#2563eb);">${esc(subTeacher)}</b>`;
          }
        }
      });

      // 2. Extra lesson in substitute teacher's view
      if (!isCancelled && sub.substituteTeacherId && perspective === "teacher") {
        const slotEl = rootEl.querySelector(`.chrx-row[data-row="${sub.substituteTeacherId}"] .chrx-slot[data-day="${sub.day}"][data-period="${sub.period}"]`);
        if (slotEl && !slotEl.querySelector(`.chrx-vkarta--substitute[data-sub-id="${sub.id}"]`)) {
          slotEl.classList.remove("empty");
          const origCard = (S.cards || []).find(c => (c.id || `placed_${c.lessonId}_${c.day}_${c.period}`) === sub.cardId);
          const lesson = origCard && S._idx?.lessonById?.[origCard.lessonId];
          const className = (lesson?.classIds || []).map(cid => S._idx?.classById?.[cid]?.name).filter(Boolean).join(", ") || "Class";
          const subjectName = (lesson?.subjectId && S._idx?.subjectById?.[lesson.subjectId]?.name) || "Lesson";

          const subCardHtml = `
            <div class="chrx-vkarta chrx-vkarta--substitute" data-sub-id="${sub.id}" role="button" tabindex="0"
                 style="border-left: 3px solid #10b981; background: #ecfdf5; box-shadow: 0 1px 2px rgba(0,0,0,0.05); padding: 2px 4px;">
              <div class="chrx-vk-line1" style="color:#065f46; font-weight:600;">${esc(className)}</div>
              <div class="chrx-vk-line2" style="color:#047857; font-size:10px;">${esc(subjectName)} <span style="background:#10b981;color:#fff;border-radius:3px;padding:0 3px;font-size:9px;">Sub</span></div>
            </div>
          `;
          slotEl.innerHTML = subCardHtml;
        }

        // Focus mode board
        if (window.APP?.editor?.viewMode === "focus") {
          const select = rootEl.querySelector("select[data-focus-entity]");
          if (select && select.value === sub.substituteTeacherId) {
            const focusSlot = rootEl.querySelector(`.chrx-focus-slot[data-day="${sub.day}"][data-period="${sub.period}"]`);
            if (focusSlot && !focusSlot.querySelector(`.chrx-vkarta--substitute[data-sub-id="${sub.id}"]`)) {
              focusSlot.classList.remove("empty");
              const origCard = (S.cards || []).find(c => (c.id || `placed_${c.lessonId}_${c.day}_${c.period}`) === sub.cardId);
              const lesson = origCard && S._idx?.lessonById?.[origCard.lessonId];
              const className = (lesson?.classIds || []).map(cid => S._idx?.classById?.[cid]?.name).filter(Boolean).join(", ") || "Class";
              const subjectName = (lesson?.subjectId && S._idx?.subjectById?.[lesson.subjectId]?.name) || "Lesson";

              focusSlot.innerHTML = `
                <div class="chrx-vkarta chrx-vkarta--substitute" data-sub-id="${sub.id}" role="button" tabindex="0"
                     style="border-left: 3px solid #10b981; background: #ecfdf5; box-shadow: 0 1px 2px rgba(0,0,0,0.05); padding: 2px 4px;">
                  <div class="chrx-vk-line1" style="color:#065f46; font-weight:600;">${esc(className)}</div>
                  <div class="chrx-vk-line2" style="color:#047857; font-size:10px;">${esc(subjectName)} <span style="background:#10b981;color:#fff;border-radius:3px;padding:0 3px;font-size:9px;">Sub</span></div>
                </div>
              `;
            }
          }
        }
      }
    });
  }

  // ---------------- wire ----------------
  window.addEventListener("app:substitutions", open);

  // Wire date changes from editor date input
  function wireDateControl() {
    const input = document.getElementById("editor-date-input");
    const clearBtn = document.getElementById("editor-date-clear");
    if (input && !input._chrxWired) {
      input._chrxWired = true;
      input.addEventListener("change", (e) => {
        window.APP.editor = window.APP.editor || {};
        window.APP.editor.date = e.target.value || null;
        if (window.APP?.substitution) window.APP.substitution.date = e.target.value || todayYmd();
        const editorRoot = document.getElementById("editor-root");
        if (editorRoot && window.Editor?.render) window.Editor.render(editorRoot);
      });
    }
    if (clearBtn && !clearBtn._chrxWired) {
      clearBtn._chrxWired = true;
      clearBtn.addEventListener("click", () => {
        if (input) input.value = "";
        window.APP.editor = window.APP.editor || {};
        window.APP.editor.date = null;
        const editorRoot = document.getElementById("editor-root");
        if (editorRoot && window.Editor?.render) window.Editor.render(editorRoot);
      });
    }
  }

  if (typeof document !== "undefined") {
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", wireDateControl);
    } else {
      wireDateControl();
    }
    document.addEventListener("app:school-loaded", wireDateControl);
  }

  // ---------------- exports ----------------
  window.Substitution = {
    open, close, renderTab,
    el, esc, todayYmd, ymdToDay,
    mutateCompat,
    recordAbsence, removeAbsence, getAbsences,
    assignSubstitutions, cancelSubstitution, reassignSubstitution, getSubstitutions,
    applyGridOverrides, wireDateControl,
    // plan lifecycle (ported from the school's standalone planner)
    buildPlan, loadPlan, persistPlan, projectAssignments,
    setSubstitute, setCancelled, movePeriod, mergeSlots, unmergeSlots,
    planSmartFill, applySmartFill, undoSmartFill,
  };
})();

